import React, { useState, useEffect } from 'react';
import axios from 'axios';

function AdminManageBookings() {
  const [bookings, setBookings] = useState([]);

  useEffect(() => {
    axios.get('http://localhost:8082/admin/manage-bookings')
      .then(response => {
        setBookings(response.data);
      })
      .catch(error => {
        console.error("Error fetching bookings:", error);
      });
  }, []);

  const handleApprove = (bookingId) => {
    axios.post('http://localhost:8082/admin/approve-booking', { bookingId })
      .then(response => {
        alert(response.data.message);
        setBookings(bookings.filter(booking => booking.booking_id !== bookingId));
      })
      .catch(error => {
        console.error("Error approving booking:", error);
      });
  };

  const handleReject = (bookingId) => {
    axios.post('http://localhost:8082/admin/reject-booking', { bookingId })
      .then(response => {
        alert(response.data.message);
        setBookings(bookings.filter(booking => booking.booking_id !== bookingId));
      })
      .catch(error => {
        console.error("Error rejecting booking:", error);
      });
  };

  return (
    <div>
      <h2>Manage Bookings</h2>
      <table className="table">
        <thead>
          <tr>
            <th>Booking ID</th>
            <th>Faculty Name</th>
            <th>Booking Details</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {bookings.map(booking => (
            <tr key={booking.booking_id}>
              <td>{booking.booking_id}</td>
              <td>{booking.faculty_name}</td>
              <td>{booking.booking_details}</td>
              <td>
                <button onClick={() => handleApprove(booking.booking_id)} className="btn btn-success">Approve</button>
                <button onClick={() => handleReject(booking.booking_id)} className="btn btn-danger">Reject</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default AdminManageBookings;
